{
  "items": [
    {
      "name": "Polynomial.degree_multiset_prod_le",
      "module_name": "Mathlib.Algebra.Polynomial.BigOperators",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommSemiring R] (t : Multiset (Polynomial R)),\n  t.prod.degree ≤ (Multiset.map Polynomial.degree t).sum"
    },
    {
      "name": "Polynomial.degree_prod_le",
      "module_name": "Mathlib.Algebra.Polynomial.BigOperators",
      "kind": "theorem",
      "type": "∀ {R : Type u} {ι : Type w} (s : Finset ι) [inst : CommSemiring R] (f : ι → Polynomial R),\n  (∏ i ∈ s, f i).degree ≤ ∑ i ∈ s, (f i).degree"
    },
    {
      "name": "Polynomial.natDegree_prod_le",
      "module_name": "Mathlib.Algebra.Polynomial.BigOperators",
      "kind": "theorem",
      "type": "∀ {R : Type u} {ι : Type w} (s : Finset ι) [inst : CommSemiring R] (f : ι → Polynomial R),\n  (∏ i ∈ s, f i).natDegree ≤ ∑ i ∈ s, (f i).natDegree"
    },
    {
      "name": "Matrix.det_matrixOfPolynomials",
      "module_name": "Mathlib.LinearAlgebra.Matrix.Block",
      "kind": "theorem",
      "type": "∀ {R : Type v} [inst : CommRing R] {n : ℕ} (p : Fin n → Polynomial R),\n  (∀ (i : Fin n), (p i).natDegree = ↑i) → (∀ (i : Fin n), (p i).Monic) → (Matrix.of fun i j => (p j).coeff ↑i).det = 1"
    },
    {
      "name": "eval_det",
      "module_name": "Mathlib.RingTheory.MatrixPolynomialAlgebra",
      "kind": "theorem",
      "type": "∀ {n : Type w} [inst : DecidableEq n] [inst_1 : Fintype n] {R : Type u_3} [inst_2 : CommRing R]\n  (M : Matrix n n (Polynomial R)) (r : R),\n  Polynomial.eval r M.det = (Polynomial.eval ((Matrix.scalar n) r) (matPolyEquiv M)).det"
    },
    {
      "name": "MvPolynomial.degreeOf_prod_le",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] {ι : Type u_3} (i : σ) (s : Finset ι) (f : ι → MvPolynomial σ R),\n  MvPolynomial.degreeOf i (∏ j ∈ s, f j) ≤ ∑ j ∈ s, MvPolynomial.degreeOf i (f j)"
    }
  ]
}
